-- Table and column comments, so the data dictionary lives inside HANA. Optional; run after 01_create_tables.sql. Generated by `python -m backend.database.hana_core`; do not edit. Change hana_core_spec.py and regenerate.

COMMENT ON TABLE "COUNTRY" IS 'The 217 World Bank countries, with the ISO-2 code and retail label the project''s data needs. The join key for tariffs, ports, demand and suppliers.';
COMMENT ON COLUMN "COUNTRY"."ISO3" IS 'ISO 3166-1 alpha-3 country code as the World Bank writes it (CHI for the Channel Islands, which ISO does not code). The key every country reference points at.';
COMMENT ON COLUMN "COUNTRY"."ISO2" IS 'ISO 3166-1 alpha-2 code. Filled only for the countries the cleaned data uses; NULL for the rest, so it is not a complete ISO table.';
COMMENT ON COLUMN "COUNTRY"."NAME" IS 'Country name as the World Bank writes it.';
COMMENT ON COLUMN "COUNTRY"."REGION" IS 'World Bank region.';
COMMENT ON COLUMN "COUNTRY"."INCOME_GROUP" IS 'World Bank income group.';
COMMENT ON COLUMN "COUNTRY"."RETAIL_LABEL" IS 'The label the retail dataset uses for this country (''EIRE'', ''RSA'', ...). NULL if the retail data never names it. Matches DEMAND.LOCATION_ID.';
COMMENT ON COLUMN "COUNTRY"."PROVENANCE" IS 'Where the row''s facts come from: REAL, DERIVED, SYNTHETIC or AUTHORED (see DATA_READINESS_REPORT.md section 4).';

COMMENT ON TABLE "PORT" IS 'All 3,669 World Port Index ports (a 2017 snapshot), keyed by the index''s own number.';
COMMENT ON COLUMN "PORT"."PORT_ID" IS 'World Port Index INDEX_NO.';
COMMENT ON COLUMN "PORT"."PORT_NAME" IS 'Port name as the World Port Index writes it, upper case. Not unique: some names repeat within a country, so the key is PORT_ID.';
COMMENT ON COLUMN "PORT"."COUNTRY_ISO2" IS 'The World Port Index''s 2-letter country code. Not a foreign key: COUNTRY.ISO2 is filled only for some countries.';
COMMENT ON COLUMN "PORT"."COUNTRY_ISO3" IS 'ISO-3 country, derived from COUNTRY_ISO2 where the country table can map it; NULL for the rest.';
COMMENT ON COLUMN "PORT"."LATITUDE" IS 'Decimal degrees, north positive.';
COMMENT ON COLUMN "PORT"."LONGITUDE" IS 'Decimal degrees, east positive.';
COMMENT ON COLUMN "PORT"."HARBOR_SIZE" IS 'World Port Index harbour size code (L, M, S, V). NULL where the index does not report it.';
COMMENT ON COLUMN "PORT"."HARBOR_TYPE" IS 'World Port Index harbour type code. NULL where not reported.';
COMMENT ON COLUMN "PORT"."SOURCE" IS 'The dataset and vintage the row comes from.';
COMMENT ON COLUMN "PORT"."PROVENANCE" IS 'Where the row''s facts come from: REAL, DERIVED, SYNTHETIC or AUTHORED (see DATA_READINESS_REPORT.md section 4).';

COMMENT ON TABLE "PRODUCT" IS 'Every product that has a sale line: name, median price, ABC class and volume from the corrected net demand.';
COMMENT ON COLUMN "PRODUCT"."PRODUCT_ID" IS 'The retail stock code, as text (''85123A'', ''22197''). Never a number.';
COMMENT ON COLUMN "PRODUCT"."PRODUCT_NAME" IS 'The description most often used for the code.';
COMMENT ON COLUMN "PRODUCT"."AVG_UNIT_PRICE_GBP" IS 'Median unit price of the product''s net-positive sale lines, in GBP. DOUBLE and not DECIMAL because a few medians of two prices carry floating-point noise in the cleaned file that must not be rounded away silently. NULL for a product whose every sale was cancelled.';
COMMENT ON COLUMN "PRODUCT"."ABC_CLASS" IS 'A, B or C by cumulative net revenue (80% / 95%). A revenue ranking, not a measure of criticality.';
COMMENT ON COLUMN "PRODUCT"."NET_UNITS" IS 'Units sold net of cancellations.';
COMMENT ON COLUMN "PRODUCT"."NET_REVENUE_GBP" IS 'Net units times price, in GBP.';
COMMENT ON COLUMN "PRODUCT"."ACTIVE_DAYS" IS 'Days with a net sale.';
COMMENT ON COLUMN "PRODUCT"."FIRST_SALE_DATE" IS 'First day with a net sale. NULL if none.';
COMMENT ON COLUMN "PRODUCT"."LAST_SALE_DATE" IS 'Last day with a net sale. NULL if none.';
COMMENT ON COLUMN "PRODUCT"."IS_FORECAST_SERIES" IS 'True for the 40 products of the modeling panel.';
COMMENT ON COLUMN "PRODUCT"."PROVENANCE" IS 'Where the row''s facts come from: REAL, DERIVED, SYNTHETIC or AUTHORED (see DATA_READINESS_REPORT.md section 4).';

COMMENT ON TABLE "WAREHOUSE" IS 'Three synthetic warehouses in India that the inventory ledger is split across.';
COMMENT ON COLUMN "WAREHOUSE"."WAREHOUSE_ID" IS 'Warehouse code (the city''s name).';
COMMENT ON COLUMN "WAREHOUSE"."WAREHOUSE_NAME" IS 'Display name, marked SYNTHETIC.';
COMMENT ON COLUMN "WAREHOUSE"."CITY" IS 'City.';
COMMENT ON COLUMN "WAREHOUSE"."COUNTRY_ISO3" IS 'Country of the warehouse.';
COMMENT ON COLUMN "WAREHOUSE"."NEAREST_PORT_ID" IS 'Nearest World Port Index port; NULL for inland Delhi.';
COMMENT ON COLUMN "WAREHOUSE"."PROVENANCE" IS 'Where the row''s facts come from: REAL, DERIVED, SYNTHETIC or AUTHORED (see DATA_READINESS_REPORT.md section 4).';

COMMENT ON TABLE "SUPPLIER" IS 'Eight fictitious suppliers, named SYNTHETIC. Nominal master data only: no status, so the normal baseline has every supplier active.';
COMMENT ON COLUMN "SUPPLIER"."SUPPLIER_ID" IS 'Supplier code S001-S008. Unique here; it repeats in SUPPLIER_PRODUCT, whose key is the pair.';
COMMENT ON COLUMN "SUPPLIER"."SUPPLIER_NAME" IS '''SYNTHETIC Supplier S00x'': nothing implies a real company.';
COMMENT ON COLUMN "SUPPLIER"."CITY" IS 'The hypothetical location.';
COMMENT ON COLUMN "SUPPLIER"."COUNTRY_ISO3" IS 'Country of the supplier.';
COMMENT ON COLUMN "SUPPLIER"."REGION" IS 'Country name, as the optimizer''s configuration calls it.';
COMMENT ON COLUMN "SUPPLIER"."RISK_LEVEL" IS 'Static risk tier, assigned by country. Not derived from reliability.';
COMMENT ON COLUMN "SUPPLIER"."ORIGIN_PORT_ID" IS 'The port whose lanes carry this supplier''s goods (from the optimizer''s configuration). NULL where no freight leg is modeled.';
COMMENT ON COLUMN "SUPPLIER"."PROVENANCE" IS 'Where the row''s facts come from: REAL, DERIVED, SYNTHETIC or AUTHORED (see DATA_READINESS_REPORT.md section 4).';

COMMENT ON TABLE "SUPPLIER_PRODUCT" IS 'Which supplier carries which product, with nominal capacity, unit cost, lead time and reliability. All SYNTHETIC.';
COMMENT ON COLUMN "SUPPLIER_PRODUCT"."SUPPLIER_ID" IS 'The supplier.';
COMMENT ON COLUMN "SUPPLIER_PRODUCT"."PRODUCT_ID" IS 'The product.';
COMMENT ON COLUMN "SUPPLIER_PRODUCT"."CAPACITY" IS 'Nominal maximum units of this product the supplier can provide in one planning run. The source states NO time unit and none is assumed here.';
COMMENT ON COLUMN "SUPPLIER_PRODUCT"."UNIT_COST" IS 'Cost per unit in ABSTRACT cost units: not pounds, and not commensurate with PRODUCT.AVG_UNIT_PRICE_GBP.';
COMMENT ON COLUMN "SUPPLIER_PRODUCT"."LEAD_TIME_DAYS" IS 'Days from order to shipment.';
COMMENT ON COLUMN "SUPPLIER_PRODUCT"."RELIABILITY" IS 'Share of orders delivered as promised, 0 to 1; follows the supplier''s risk tier.';
COMMENT ON COLUMN "SUPPLIER_PRODUCT"."PROVENANCE" IS 'Where the row''s facts come from: REAL, DERIVED, SYNTHETIC or AUTHORED (see DATA_READINESS_REPORT.md section 4).';

COMMENT ON TABLE "ROUTE" IS 'Ten lanes to Rotterdam: a Suez lane and a Cape lane from each of four origins, plus one rail and one air lane.';
COMMENT ON COLUMN "ROUTE"."ROUTE_ID" IS 'Lane code, e.g. SHA-ROT-SUEZ.';
COMMENT ON COLUMN "ROUTE"."ORIGIN" IS 'Origin port name as the routes have always called it.';
COMMENT ON COLUMN "ROUTE"."DESTINATION" IS 'Destination port name.';
COMMENT ON COLUMN "ROUTE"."ORIGIN_PORT_ID" IS 'Origin, as a World Port Index port.';
COMMENT ON COLUMN "ROUTE"."DESTINATION_PORT_ID" IS 'Destination, as a World Port Index port.';
COMMENT ON COLUMN "ROUTE"."TRANSPORT_MODE" IS 'sea, rail or air (lower case, as delivered).';
COMMENT ON COLUMN "ROUTE"."LANE_ROLE" IS 'PRIMARY or ALTERNATIVE. A role, never a disruption: disruption is scenario data.';
COMMENT ON COLUMN "ROUTE"."VIA" IS 'SUEZ, CAPE, RAIL or AIR.';
COMMENT ON COLUMN "ROUTE"."CHOKEPOINTS" IS 'Chokepoints the lane passes, separated by ''|''. NULL for rail and air.';
COMMENT ON COLUMN "ROUTE"."DISTANCE_KM" IS 'Kilometres. Sea lanes: summed great-circle legs along land-checked waypoints (approximate; see DISTANCE_BASIS).';
COMMENT ON COLUMN "ROUTE"."DISTANCE_BASIS" IS 'How DISTANCE_KM was obtained: WAYPOINT_POLYLINE, GREAT_CIRCLE or REPORTED_SERVICE_RANGE.';
COMMENT ON COLUMN "ROUTE"."LEGACY_DISTANCE_KM" IS 'The Phase 3 distance, kept so the correction is visible. NULL for the two lanes Phase 3 did not have.';
COMMENT ON COLUMN "ROUTE"."CAPACITY" IS 'Abstract capacity units compared with unit quantities. No time unit is stated or assumed.';
COMMENT ON COLUMN "ROUTE"."TRANSIT_TIME_DAYS" IS 'Days door to door, from the distance and an assumed speed.';
COMMENT ON COLUMN "ROUTE"."COST_PER_UNIT" IS 'Freight cost per unit in abstract cost units.';
COMMENT ON COLUMN "ROUTE"."ROUTE_NOTE" IS 'How the lane was built and what to be careful of.';
COMMENT ON COLUMN "ROUTE"."PROVENANCE" IS 'Where the row''s facts come from: REAL, DERIVED, SYNTHETIC or AUTHORED (see DATA_READINESS_REPORT.md section 4).';

COMMENT ON TABLE "TARIFF" IS 'The World Bank weighted-mean applied tariff, by country and year, exactly as published: nothing filled, interpolated or rounded.';
COMMENT ON COLUMN "TARIFF"."ORIGIN_ISO3" IS 'Country whose tariff this is.';
COMMENT ON COLUMN "TARIFF"."DEST_ISO3" IS 'Always ''ANY'': the source has no partner dimension. A sentinel, not a country, so not a foreign key.';
COMMENT ON COLUMN "TARIFF"."HS_SECTION" IS 'Always ''ALL'': the source has no product dimension.';
COMMENT ON COLUMN "TARIFF"."EFFECTIVE_YEAR" IS 'Year of the observation.';
COMMENT ON COLUMN "TARIFF"."TARIFF_RATE_PCT" IS 'Weighted-mean applied tariff, percent, at the World Bank''s own precision. DOUBLE so no value is rounded.';
COMMENT ON COLUMN "TARIFF"."IS_COUNTRY_LEVEL_PROXY" IS 'True: the value is a country-level proxy, not a country-pair by product rate.';
COMMENT ON COLUMN "TARIFF"."QUALITY_FLAG" IS 'OK, EXTREME_VALUE (above 50%), JUMP_GE_10PP (10 points or more from the previous observation) or both. Informational: no value was changed.';
COMMENT ON COLUMN "TARIFF"."SOURCE" IS 'Indicator and publisher.';
COMMENT ON COLUMN "TARIFF"."PROVENANCE" IS 'Where the row''s facts come from: REAL, DERIVED, SYNTHETIC or AUTHORED (see DATA_READINESS_REPORT.md section 4).';

COMMENT ON TABLE "DISRUPTION_EVENT" IS 'Four historical events written by hand about publicly reported events (AUTHORED), each with a verification status. Not weather data and not scenarios.';
COMMENT ON COLUMN "DISRUPTION_EVENT"."EVENT_ID" IS 'Event code.';
COMMENT ON COLUMN "DISRUPTION_EVENT"."EVENT_TYPE" IS 'Kind of event.';
COMMENT ON COLUMN "DISRUPTION_EVENT"."LOCATION" IS 'Where it happened.';
COMMENT ON COLUMN "DISRUPTION_EVENT"."START_TS" IS 'Start, no time zone.';
COMMENT ON COLUMN "DISRUPTION_EVENT"."END_TS" IS 'End; NULL if open-ended.';
COMMENT ON COLUMN "DISRUPTION_EVENT"."SEVERITY" IS 'LOW, MEDIUM, HIGH or CRITICAL.';
COMMENT ON COLUMN "DISRUPTION_EVENT"."ESTIMATED_DELAY_DAYS" IS 'The authors'' estimate of the delay in days; NULL where none is estimated.';
COMMENT ON COLUMN "DISRUPTION_EVENT"."STATUS" IS 'HISTORICAL for these events.';
COMMENT ON COLUMN "DISRUPTION_EVENT"."SOURCE_NOTE" IS 'What the event was and how far to trust the dates.';
COMMENT ON COLUMN "DISRUPTION_EVENT"."VERIFICATION_STATUS" IS 'UNVERIFIED_IN_WORKSPACE, or CORROBORATED_BY_WDI where the World Bank series confirms it.';
COMMENT ON COLUMN "DISRUPTION_EVENT"."PROVENANCE" IS 'Where the row''s facts come from: REAL, DERIVED, SYNTHETIC or AUTHORED (see DATA_READINESS_REPORT.md section 4).';

COMMENT ON TABLE "DISRUPTION_IMPACT" IS 'Which lanes a historical event blocked. An inference, labelled AUTHORED.';
COMMENT ON COLUMN "DISRUPTION_IMPACT"."EVENT_ID" IS 'The event.';
COMMENT ON COLUMN "DISRUPTION_IMPACT"."ENTITY_TYPE" IS 'ROUTE or SUPPLIER: what ENTITY_ID names.';
COMMENT ON COLUMN "DISRUPTION_IMPACT"."ENTITY_ID" IS 'A route id or a supplier id according to ENTITY_TYPE, so it has no foreign key; the validation SQL checks it.';
COMMENT ON COLUMN "DISRUPTION_IMPACT"."DELAY_DAYS" IS 'Days of delay the event caused there.';
COMMENT ON COLUMN "DISRUPTION_IMPACT"."CAPACITY_FACTOR" IS 'Share of nominal capacity left, 0 to 1.';
COMMENT ON COLUMN "DISRUPTION_IMPACT"."BASIS" IS 'Why this entity is listed.';
COMMENT ON COLUMN "DISRUPTION_IMPACT"."PROVENANCE" IS 'Where the row''s facts come from: REAL, DERIVED, SYNTHETIC or AUTHORED (see DATA_READINESS_REPORT.md section 4).';

COMMENT ON TABLE "SCENARIO" IS 'The scenarios: the normal baseline, the six of backend/config/scenarios.yaml, a Red Sea diversion and the legacy demo start. All SYNTHETIC.';
COMMENT ON COLUMN "SCENARIO"."SCENARIO_ID" IS 'Scenario code.';
COMMENT ON COLUMN "SCENARIO"."SCENARIO_NAME" IS 'Display name.';
COMMENT ON COLUMN "SCENARIO"."DESCRIPTION" IS 'What the scenario simulates.';
COMMENT ON COLUMN "SCENARIO"."SCENARIO_TYPE" IS 'BASELINE, DISRUPTION or LEGACY_STATE.';
COMMENT ON COLUMN "SCENARIO"."IS_MODELED" IS 'False if the pipeline records this kind of event but nothing acts on it yet.';
COMMENT ON COLUMN "SCENARIO"."BASED_ON_EVENT_ID" IS 'The historical event the scenario is grounded in, if any (only the Suez closure).';
COMMENT ON COLUMN "SCENARIO"."SOURCE" IS 'Where the definition comes from.';
COMMENT ON COLUMN "SCENARIO"."PROVENANCE" IS 'Where the row''s facts come from: REAL, DERIVED, SYNTHETIC or AUTHORED (see DATA_READINESS_REPORT.md section 4).';

COMMENT ON TABLE "SCENARIO_STATE" IS 'What each scenario does to which lane or supplier. Only deviations from normal are stored: absence of a row means ACTIVE / NORMAL.';
COMMENT ON COLUMN "SCENARIO_STATE"."SCENARIO_ID" IS 'The scenario.';
COMMENT ON COLUMN "SCENARIO_STATE"."ENTITY_TYPE" IS 'ROUTE or SUPPLIER: what ENTITY_ID names.';
COMMENT ON COLUMN "SCENARIO_STATE"."ENTITY_ID" IS 'A route id or a supplier id according to ENTITY_TYPE, so it has no foreign key; the validation SQL checks it.';
COMMENT ON COLUMN "SCENARIO_STATE"."STATUS" IS 'DISRUPTED, REDUCED or DELAYED.';
COMMENT ON COLUMN "SCENARIO_STATE"."CAPACITY_FACTOR" IS 'Share of nominal capacity left, 0 to 1. A placeholder for REDUCED.';
COMMENT ON COLUMN "SCENARIO_STATE"."BASIS" IS 'Why the entity is affected.';
COMMENT ON COLUMN "SCENARIO_STATE"."PROVENANCE" IS 'Where the row''s facts come from: REAL, DERIVED, SYNTHETIC or AUTHORED (see DATA_READINESS_REPORT.md section 4).';

COMMENT ON TABLE "SCENARIO_PARAM" IS 'A scenario''s numbers: duration, severity, tariff change per country.';
COMMENT ON COLUMN "SCENARIO_PARAM"."SCENARIO_ID" IS 'The scenario.';
COMMENT ON COLUMN "SCENARIO_PARAM"."PARAM_KEY" IS 'duration_days, severity or tariff_add_pct.';
COMMENT ON COLUMN "SCENARIO_PARAM"."QUALIFIER" IS 'ISO-3 country for a per-country parameter, else ''ALL''. Part of the key, so never NULL.';
COMMENT ON COLUMN "SCENARIO_PARAM"."PARAM_VALUE" IS 'Numeric value, in UNIT.';
COMMENT ON COLUMN "SCENARIO_PARAM"."PARAM_TEXT" IS 'Text value, for a parameter that is not a number.';
COMMENT ON COLUMN "SCENARIO_PARAM"."UNIT" IS 'Unit of PARAM_VALUE.';
COMMENT ON COLUMN "SCENARIO_PARAM"."BASIS" IS 'Where the number comes from.';
COMMENT ON COLUMN "SCENARIO_PARAM"."PROVENANCE" IS 'Where the row''s facts come from: REAL, DERIVED, SYNTHETIC or AUTHORED (see DATA_READINESS_REPORT.md section 4).';

COMMENT ON TABLE "INVENTORY_POLICY" IS 'The parameters the inventory simulation used, per warehouse, so the ledger can be reproduced.';
COMMENT ON COLUMN "INVENTORY_POLICY"."WAREHOUSE_ID" IS 'The warehouse.';
COMMENT ON COLUMN "INVENTORY_POLICY"."DEMAND_SHARE" IS 'Share of each product''s demand this warehouse gets; the shares sum to 1.';
COMMENT ON COLUMN "INVENTORY_POLICY"."COVER_MULTIPLIER" IS 'Multiplies the starting days of cover.';
COMMENT ON COLUMN "INVENTORY_POLICY"."SAFETY_MULTIPLIER" IS 'Multiplies the safety days.';
COMMENT ON COLUMN "INVENTORY_POLICY"."TARGET_DAYS_OF_COVER" IS 'Days of mean demand held at the start.';
COMMENT ON COLUMN "INVENTORY_POLICY"."SAFETY_DAYS" IS 'Days of mean demand held as safety stock.';
COMMENT ON COLUMN "INVENTORY_POLICY"."REPLENISH_DAYS" IS 'Days of mean demand ordered when stock falls below safety.';
COMMENT ON COLUMN "INVENTORY_POLICY"."REPLENISHMENT_LEAD_TIME_DAYS" IS 'Days between ordering and arrival. 0 means a replenishment arrives the day it is triggered.';
COMMENT ON COLUMN "INVENTORY_POLICY"."PROVENANCE" IS 'Where the row''s facts come from: REAL, DERIVED, SYNTHETIC or AUTHORED (see DATA_READINESS_REPORT.md section 4).';

COMMENT ON TABLE "INVENTORY" IS 'A SIMULATED stock ledger, one row per warehouse, product and day, with lost sales recorded. Not an observation.';
COMMENT ON COLUMN "INVENTORY"."WAREHOUSE_ID" IS 'The warehouse.';
COMMENT ON COLUMN "INVENTORY"."PRODUCT_ID" IS 'The product.';
COMMENT ON COLUMN "INVENTORY"."DATE" IS 'The day.';
COMMENT ON COLUMN "INVENTORY"."OPENING_STOCK" IS 'Units on hand at the start of the day.';
COMMENT ON COLUMN "INVENTORY"."INBOUND_QUANTITY" IS 'Units received.';
COMMENT ON COLUMN "INVENTORY"."OUTBOUND_QUANTITY" IS 'Units actually shipped.';
COMMENT ON COLUMN "INVENTORY"."CLOSING_STOCK" IS 'Units on hand at the end: opening + inbound - outbound, exactly.';
COMMENT ON COLUMN "INVENTORY"."SAFETY_STOCK" IS 'Safety stock for this warehouse and product.';
COMMENT ON COLUMN "INVENTORY"."REORDER_POINT" IS 'Reorder point; equal to safety stock under instant replenishment.';
COMMENT ON COLUMN "INVENTORY"."DEMAND_QUANTITY" IS 'Net demand allocated to this warehouse: outbound + unfilled.';
COMMENT ON COLUMN "INVENTORY"."UNFILLED_QUANTITY" IS 'Demand that could not be shipped: a lost sale, recorded not hidden.';
COMMENT ON COLUMN "INVENTORY"."STOCKOUT_FLAG" IS 'True when UNFILLED_QUANTITY is above zero.';
COMMENT ON COLUMN "INVENTORY"."PROVENANCE" IS 'Where the row''s facts come from: REAL, DERIVED, SYNTHETIC or AUTHORED (see DATA_READINESS_REPORT.md section 4).';

COMMENT ON TABLE "DEMAND" IS 'Net demand per day, product and country, with cancellations netted out and no features. Derived from the corrected sale lines.';
COMMENT ON COLUMN "DEMAND"."DATE" IS 'The day.';
COMMENT ON COLUMN "DEMAND"."PRODUCT_ID" IS 'The product.';
COMMENT ON COLUMN "DEMAND"."LOCATION_ID" IS 'The retail country label, as text (''United Kingdom'', ''EIRE''). Equivalent to COUNTRY_ISO3 (1:1) but no foreign key: the label column of COUNTRY is neither a key nor unique.';
COMMENT ON COLUMN "DEMAND"."COUNTRY_ISO3" IS 'The customer''s country.';
COMMENT ON COLUMN "DEMAND"."DEMAND_QUANTITY" IS 'Net units demanded that day: sale lines less the cancellations that reversed them. Always above zero: a day with no net sale has no row.';
COMMENT ON COLUMN "DEMAND"."N_ORDER_LINES" IS 'Sale lines behind the number.';
COMMENT ON COLUMN "DEMAND"."N_OUTLIER_LINES" IS 'Of those, lines flagged as unusually large (kept, not removed).';
COMMENT ON COLUMN "DEMAND"."PROVENANCE" IS 'Where the row''s facts come from: REAL, DERIVED, SYNTHETIC or AUTHORED (see DATA_READINESS_REPORT.md section 4).';

COMMENT ON TABLE "DEMAND_MODELING_PANEL" IS 'The 40 forecastable series on a dense daily calendar (a day without a sale is 0), with lag and rolling features and a time split.';
COMMENT ON COLUMN "DEMAND_MODELING_PANEL"."DATE" IS 'The day.';
COMMENT ON COLUMN "DEMAND_MODELING_PANEL"."PRODUCT_ID" IS 'The product.';
COMMENT ON COLUMN "DEMAND_MODELING_PANEL"."LOCATION_ID" IS 'The retail country label. Always ''United Kingdom'' in this panel. No foreign key (see DEMAND.LOCATION_ID), and the panel has no ISO-3 column.';
COMMENT ON COLUMN "DEMAND_MODELING_PANEL"."DEMAND_QUANTITY" IS 'Net units that day; 0 on a day without a sale.';
COMMENT ON COLUMN "DEMAND_MODELING_PANEL"."LAG_1" IS 'Demand one day earlier. NULL at the start of a series. Whole numbers stored as the float the cleaned file delivers.';
COMMENT ON COLUMN "DEMAND_MODELING_PANEL"."LAG_2" IS 'Demand two days earlier.';
COMMENT ON COLUMN "DEMAND_MODELING_PANEL"."LAG_7" IS 'Demand seven days earlier.';
COMMENT ON COLUMN "DEMAND_MODELING_PANEL"."LAG_14" IS 'Demand fourteen days earlier.';
COMMENT ON COLUMN "DEMAND_MODELING_PANEL"."LAG_28" IS 'Demand twenty-eight days earlier.';
COMMENT ON COLUMN "DEMAND_MODELING_PANEL"."ROLLING_MEAN_7" IS 'Mean of the previous 7 days, current day excluded (no leakage). DOUBLE keeps full precision.';
COMMENT ON COLUMN "DEMAND_MODELING_PANEL"."ROLLING_MEAN_14" IS 'Mean of the previous 14 days.';
COMMENT ON COLUMN "DEMAND_MODELING_PANEL"."ROLLING_MEAN_28" IS 'Mean of the previous 28 days.';
COMMENT ON COLUMN "DEMAND_MODELING_PANEL"."DAY_OF_WEEK" IS '0 = Monday to 6 = Sunday.';
COMMENT ON COLUMN "DEMAND_MODELING_PANEL"."MONTH" IS '1 to 12.';
COMMENT ON COLUMN "DEMAND_MODELING_PANEL"."DISRUPTION_ACTIVE" IS 'Constant False: no disruption overlaps 2010-2011. Do not use as a feature.';
COMMENT ON COLUMN "DEMAND_MODELING_PANEL"."SPLIT" IS 'train, val or test: a chronological 70/15/15 split.';
COMMENT ON COLUMN "DEMAND_MODELING_PANEL"."HAS_OUTLIER_LINE" IS 'True if an unusually large order line contributes to the day.';
COMMENT ON COLUMN "DEMAND_MODELING_PANEL"."PROVENANCE" IS 'Where the row''s facts come from: REAL, DERIVED, SYNTHETIC or AUTHORED (see DATA_READINESS_REPORT.md section 4).';
